import json, subprocess

URL = "http://127.0.0.1:40573/mcp/f176ad24d31f48108fcc4d7ea5a1763b"

def rpc(method, params, _id=1):
    payload = json.dumps({'jsonrpc':'2.0','id':_id,'method':method,'params':params})
    cmd = "curl -s -X POST " + URL + ' -H "Content-Type: application/json" -H "Accept: application/json, text/event-stream" -d ' + json.dumps(payload)
    return subprocess.run(cmd, shell=True, capture_output=True, text=True).stdout

def api_search(query, top_k=5):
    return rpc("tools/call", {"name":"api_search","arguments":{"query":query,"top_k":top_k}})

def api_fetch(method, url, params=None, body=None):
    p = {"method":method,"url":url,
         "params": params if isinstance(params,str) else (json.dumps(params) if params else None),
         "body": body if isinstance(body,str) else (json.dumps(body) if body is not None else None)}
    return rpc("tools/call", {"name":"api_fetch","arguments":p})

def extract(s):
    try:
        d = json.loads(s)
        return d["result"]["content"][0]["text"]
    except Exception:
        return s

def world_search(query, top_k=5):
    """Search world API endpoints, return list of result dicts."""
    txt = extract(api_search(query, top_k))
    d = json.loads(txt)
    return d["results"]

def world_fetch(method, url, params=None, body=None):
    """Call a world endpoint; return parsed JSON or raw text."""
    txt = extract(api_fetch(method, url, params, body))
    try:
        return json.loads(txt)
    except Exception:
        return txt

